package org.jlinalg.sequence;

import java.io.*;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.function.BooleanSupplier;

/** Bounded UTF-8 sparse expression/metadata intake and captured LinkPeaks audit protocol. */
public final class SignacLinkIO {
    private SignacLinkIO() { }
    public record Limits(int features,int cells,int entries,long bytes,int lineCharacters,int backgroundValues) {
        public Limits {if(features<1||features>2_000_000||cells<2||cells>2_000_000||entries<0||entries>20_000_000||bytes<1||lineCharacters<32||lineCharacters>1_000_000||backgroundValues<1||backgroundValues>20_000_000)throw new IllegalArgumentException("Invalid LinkPeaks intake bounds");}
        public static Limits defaults(){return new Limits(2_000_000,2_000_000,10_000_000,2_000_000_000L,16384,2_000_000);}
    }
    public record Metadata(double gc,double length,Double count) {
        public Metadata {if(!Double.isFinite(gc)||gc<0||gc>100||!Double.isFinite(length)||length<=0||count!=null&&(!Double.isFinite(count)||count<0))throw new IllegalArgumentException("Require finite GC percentage, positive sequence length and optional nonnegative count metadata");}
    }
    public record Captured(List<SignacPeakLinks.Background> backgrounds,List<SignacPeakLinks.Link> links) {public Captured{backgrounds=List.copyOf(backgrounds);links=List.copyOf(links);}}
    private record Entry(int cell,int feature,double value) { }
    public static SignacPeakLinks.Sparse readExpression(Path matrix,Path features,Path cells,Limits limits,BooleanSupplier cancelled)throws IOException {
        List<String> rows=ids(features,limits.features,limits,cancelled),columns=ids(cells,limits.cells,limits,cancelled);Entry[] entries;
        try(var in=reader(matrix,limits.bytes)){
            String header=line(in,limits.lineCharacters);if(header==null||!header.matches("(?i)%%MatrixMarket matrix coordinate (real|integer) general"))throw new IOException("Expression requires uncompressed Matrix Market coordinate real/integer general");String dimensions=next(in,limits.lineCharacters,cancelled);String[] d=split(dimensions,3);int nr=integer(d[0],1,limits.features),nc=integer(d[1],2,limits.cells),n=integer(d[2],0,limits.entries);if(nr!=rows.size()||nc!=columns.size())throw new IOException("Expression shape disagrees with explicit feature/cell identities");entries=new Entry[n];String value;int at=0;
            while((value=next(in,limits.lineCharacters,cancelled))!=null){if(at>=n)throw new IOException("Excess expression coordinate entries");String[] fields=split(value,3);double numeric=finite(fields[2]);if(header.toLowerCase(Locale.ROOT).contains(" integer ")&&(!fields[2].matches("[+-]?[0-9]+")||Math.abs(numeric)>SignacFragments.MAX_EXACT))throw new IOException("Integer expression tokens require exact signed integers within2^53-1");entries[at++]=new Entry(integer(fields[1],1,nc)-1,integer(fields[0],1,nr)-1,numeric);}if(at!=n)throw new IOException("Too few expression coordinate entries");
        }
        int[] checks={0};Arrays.sort(entries,(a,b)->{if((++checks[0]&4095)==0)SignacFragments.check(cancelled);int c=Integer.compare(a.cell,b.cell);return c==0?Integer.compare(a.feature,b.feature):c;});int[] p=new int[columns.size()+1],indices=new int[entries.length];double[] values=new double[entries.length];
        for(int i=0;i<entries.length;i++){if((i&4095)==0)SignacFragments.check(cancelled);Entry e=entries[i];if(i>0&&e.cell==entries[i-1].cell&&e.feature==entries[i-1].feature)throw new IOException("Duplicate real expression coordinates are ambiguous; explicitly aggregate with provenance before analysis");p[e.cell+1]++;indices[i]=e.feature;values[i]=e.value;}for(int i=0;i<columns.size();i++)p[i+1]+=p[i];return new SignacPeakLinks.Sparse(rows,columns,p,indices,values);
    }
    public static List<String> ids(Path path,int maximum,Limits limits,BooleanSupplier cancelled)throws IOException{List<String> result=new ArrayList<>();Set<String> seen=new HashSet<>();try(var in=reader(path,limits.bytes)){String value;while((value=line(in,4094))!=null){SignacFragments.check(cancelled);if(result.size()>=maximum)throw new IOException("Too many link identities");SignacFragments.identity(value);if(!seen.add(value))throw new IOException("Repeated link identity");result.add(value);}}if(result.isEmpty())throw new IOException("Empty identity file");return List.copyOf(result);}
    public static List<SignacFragments.Region> peaks(Path path,List<String> features,Limits limits,BooleanSupplier cancelled)throws IOException{List<SignacFragments.Region> result=new ArrayList<>();for(String[] row:table(path,"chromosome\tstart\tend",3,limits.features,limits,cancelled))result.add(new SignacFragments.Region(row[0],integer(row[1],1,536870912),integer(row[2],1,536870912)));if(result.size()!=features.size())throw new IOException("Peak range/feature count differs");for(int i=0;i<result.size();i++)if(!result.get(i).name().equals(features.get(i)))throw new IOException("Peak matrix identities must equal chromosome-start-end in exact range order");return List.copyOf(result);}
    public static List<SignacPeakLinks.Gene> genes(Path path,Limits limits,BooleanSupplier cancelled)throws IOException{List<SignacPeakLinks.Gene> result=new ArrayList<>();for(String[] row:table(path,"chromosome\tstart\tend\tstrand\tgene_id\tgene_name",6,limits.features,limits,cancelled))result.add(new SignacPeakLinks.Gene(row[0],integer(row[1],1,536870912),integer(row[2],1,536870912),row[3],row[4],row[5]));return List.copyOf(result);}
    public static List<Metadata> metadata(Path path,List<String> peaks,Limits limits,BooleanSupplier cancelled)throws IOException{List<Metadata> result=new ArrayList<>();for(String[] row:table(path,"peak_id\tGC.percent\tsequence.length\tcount",4,limits.features,limits,cancelled)){if(result.size()>=peaks.size()||!row[0].equals(peaks.get(result.size())))throw new IOException("Peak metadata identities/order differ");result.add(new Metadata(finite(row[1]),finite(row[2]),row[3].isEmpty()?null:finite(row[3])));}if(result.size()!=peaks.size())throw new IOException("Missing peak metadata rows");boolean any=result.stream().anyMatch(v->v.count!=null),all=result.stream().allMatch(v->v.count!=null);if(any&&!all)throw new IOException("Use a complete precomputed count column or leave every count field blank");return List.copyOf(result);}
    public static void writeExpression(SignacPeakLinks.Sparse matrix,Path path,BooleanSupplier cancelled)throws IOException{int[] p=matrix.pointers(),rows=matrix.rows();double[] values=matrix.values();try(var out=Files.newBufferedWriter(path,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){out.write("%%MatrixMarket matrix coordinate real general\n"+matrix.features().size()+" "+matrix.cells().size()+" "+values.length+"\n");for(int col=0;col<matrix.cells().size();col++)for(int k=p[col];k<p[col+1];k++){if((k&4095)==0)SignacFragments.check(cancelled);out.write((rows[k]+1)+" "+(col+1)+" "+values[k]+"\n");}}}
    public static Captured readCaptured(Path worker,Limits limits,BooleanSupplier cancelled)throws IOException {
        Map<String,List<String>> pools=new LinkedHashMap<>();for(String[] row:table(worker.resolve("pools.tsv"),"gene\tordinal\tpeak",3,limits.backgroundValues,limits,cancelled)){List<String> values=pools.computeIfAbsent(row[0],k->new ArrayList<>());if(integer(row[1],1,Integer.MAX_VALUE)!=values.size()+1)throw new IOException("Background pool order differs");values.add(row[2]);}pools.replaceAll((k,v)->List.copyOf(v));
        Map<String,List<String>> ids=new HashMap<>();Map<String,List<Double>> coefficients=new HashMap<>();for(String[] row:table(worker.resolve("background.tsv"),"gene\tpeak\tdraw\tbackground_peak\tcoefficient",5,limits.backgroundValues,limits,cancelled)){String key=row[0]+'\0'+row[1];List<String> names=ids.computeIfAbsent(key,k->new ArrayList<>());if(integer(row[2],1,Integer.MAX_VALUE)!=names.size()+1)throw new IOException("Background draw order differs");names.add(row[3]);coefficients.computeIfAbsent(key,k->new ArrayList<>()).add(finite(row[4]));}
        List<SignacPeakLinks.Background> backgrounds=new ArrayList<>();Set<String> seen=new HashSet<>();for(String[] row:table(worker.resolve("pairs.tsv"),"gene\tpeak\tcoefficient\tzscore\tpvalue\tretained",6,limits.backgroundValues,limits,cancelled)){String key=row[0]+'\0'+row[1];if(!seen.add(key)||!ids.containsKey(key)||!pools.containsKey(row[0]))throw new IOException("Repeated/incomplete captured pair");if(!Set.of("true","false").contains(row[5]))throw new IOException("Invalid retained-link Boolean");backgrounds.add(new SignacPeakLinks.Background(row[0],row[1],finite(row[2]),ids.get(key),coefficients.get(key).stream().mapToDouble(Double::doubleValue).toArray(),extended(row[3]),finite(row[4]),Boolean.parseBoolean(row[5]),pools.get(row[0])));}
        if(!seen.equals(ids.keySet()))throw new IOException("Unreferenced background draws");List<SignacPeakLinks.Link> links=new ArrayList<>();for(String[] row:table(worker.resolve("links.tsv"),"chromosome\tstart\tend\tgene\tpeak\tcoefficient\tzscore\tpvalue",8,limits.backgroundValues,limits,cancelled))links.add(new SignacPeakLinks.Link(row[0],integer(row[1],1,536870912),integer(row[2],1,536870912),row[3],row[4],finite(row[5]),extended(row[6]),finite(row[7])));return new Captured(backgrounds,links);
    }
    public static List<String[]> table(Path path,String header,int columns,int maximum,Limits limits,BooleanSupplier cancelled)throws IOException{List<String[]> result=new ArrayList<>();try(var in=reader(path,limits.bytes)){if(!header.equals(line(in,limits.lineCharacters)))throw new IOException("Unexpected LinkPeaks TSV header: "+path.getFileName());String raw;while((raw=line(in,limits.lineCharacters))!=null){SignacFragments.check(cancelled);String[] fields=raw.split("\t",-1);if(fields.length!=columns||result.size()>=maximum)throw new IOException("Ragged/excessive LinkPeaks table");result.add(fields);}}return result;}
    private static BufferedReader reader(Path path,long maximum)throws IOException{if(!Files.isRegularFile(path)||Files.size(path)>maximum)throw new IOException("LinkPeaks input/table unavailable or exceeds byte bound");return new BufferedReader(new InputStreamReader(Files.newInputStream(path),StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT)));}
    private static String line(BufferedReader in,int maximum)throws IOException{StringBuilder value=new StringBuilder();int c;while((c=in.read())>=0){if(c=='\n')break;if(value.length()>=maximum)throw new IOException("LinkPeaks input line exceeds its bound");value.append((char)c);}if(c<0&&value.isEmpty())return null;if(!value.isEmpty()&&value.charAt(value.length()-1)=='\r')value.setLength(value.length()-1);return value.toString();}
    private static String next(BufferedReader in,int maximum,BooleanSupplier cancelled)throws IOException{String value;while((value=line(in,maximum))!=null){SignacFragments.check(cancelled);if(!value.startsWith("%"))return value;}return null;}
    private static String[] split(String value,int n)throws IOException{if(value==null)throw new IOException("Missing matrix dimensions/coordinate");String[] fields=value.strip().split("\\s+");if(fields.length!=n)throw new IOException("Ragged matrix dimensions/coordinate");return fields;}
    private static int integer(String value,int min,int max)throws IOException{try{if(!value.matches("[0-9]+"))throw new NumberFormatException();long n=Long.parseLong(value);if(n<min||n>max)throw new NumberFormatException();return(int)n;}catch(NumberFormatException error){throw new IOException("Integer token outside LinkPeaks bounds",error);}}
    private static double finite(String value)throws IOException{double n=extended(value);if(!Double.isFinite(n))throw new IOException("Nonfinite LinkPeaks numeric input");return n;}
    private static double extended(String value)throws IOException{try{if(value.equals("Inf"))return Double.POSITIVE_INFINITY;if(value.equals("-Inf"))return Double.NEGATIVE_INFINITY;double n=Double.parseDouble(value);if(Double.isNaN(n))throw new NumberFormatException();return n;}catch(NumberFormatException error){throw new IOException("Invalid LinkPeaks numeric token",error);}}
}
